        'def is_newer_version(latest: str, current: str) -> bool:\n'
        '    """Return True if latest is strictly greater than current."""\n'
        '    norm_latest = str(latest or "0").strip().lstrip("vV")\n'
        '    norm_current = str(current or "0").strip().lstrip("vV")\n'
        '    if norm_latest == norm_current:\n'
        '        return False\n'
        '\n'
        '    try:\n'
        '        from packaging.version import InvalidVersion, parse as parse_version\n'
        '    except ImportError:\n'
        '        InvalidVersion = None  # type: ignore[assignment,misc]\n'
        '        parse_version = None  # type: ignore[assignment]\n'
        '\n'
        '    if parse_version is not None:\n'
        '        try:\n'
        '            return parse_version(norm_latest) > parse_version(norm_current)\n'
        '        except InvalidVersion:  # type: ignore[misc]\n'
        '            pass\n'
        '\n'
        '    pre_ranks = {"dev": -4, "a": -3, "alpha": -3, "b": -2, "beta": -2, "rc": -1, "c": -1}\n'
        '    semver_re = re.compile(\n'
        '        r"^([0-9]+(?:\\.[0-9]+)*)(?:[._-]?(dev|alpha|beta|rc|a|b|c)[._-]?([0-9]*))?$",\n'
        '        re.IGNORECASE,\n'
        '    )\n'
        '\n'
        '    def _key(ver: str) -> tuple[Any, ...]:\n'
        '        m = semver_re.match(ver)\n'
        '        if m:\n'
        '            nums = tuple(int(part) for part in m.group(1).split("."))\n'
        '            tag = (m.group(2) or "").lower()\n'
        '            if not tag:\n'
        '                return (1, nums, 0, 0)\n'
        '            return (1, nums, pre_ranks[tag], int(m.group(3) or 0))\n'
        '        tokens = [\n'
        '            (0, int(tok)) if tok.isdigit() else (-1, tok.lower())\n'
        '            for tok in re.split(r"[._-]+", ver)\n'
        '            if tok\n'
        '        ]\n'
        '        return (0, tuple(tokens))\n'
        '\n'
        '    return _key(norm_latest) > _key(norm_current)\n'
