        '\n'
        'class HubController:\n'
        '    """Handles Telegram commands, callback queries, and step flows for W1bbex Hub."""\n'
        '\n'
        '    def __init__(self, cardinal: Any) -> None:\n'
        '        self.cardinal = cardinal\n'
        '        self.tg = cardinal.telegram\n'
        '        self.bot = self.tg.bot\n'
        '\n'
        '    def _alert(self, c: CallbackQuery, text: str, show_alert: bool = True) -> Any:\n'
        '        self.bot.answer_callback_query(c.id, text, show_alert=show_alert)\n'
        '        return CB_ANSWERED\n'
        '\n'
        '    def _send_html(self, chat_id: int, text: str, **kw: Any) -> Any:\n'
        '        markup = kw.pop("reply_markup", None)\n'
