        '            lambda t, rm: self.bot.send_message(\n'
        '                chat_id,\n'
        '                t,\n'
        '                parse_mode="HTML",\n'
        '                **({**kw, "reply_markup": rm} if rm is not None else kw),\n'
        '            ),\n'
        '            text,\n'
        '            reply_markup=markup,\n'
        '        )\n'
        '\n'
        '    def _edit_html(self, text: str, chat_id: int, message_id: int, **kw: Any) -> Any:\n'
        '        markup = kw.pop("reply_markup", None)\n'
        '        return _call_tg_html(\n'
