        '            self._edit_html(text, msg_obj.chat.id, msg_obj.id, reply_markup=kb)\n'
        '            return CB_ANSWERED\n'
        '        text, kb = render_hub_update_error(message)\n'
        '        self._edit_html(text, msg_obj.chat.id, msg_obj.id, reply_markup=kb)\n'
        '        return CB_ANSWERED\n'
        '\n'
        '    def hub_command(self, message: Message) -> None:\n'
        '        if not _is_authorized(self.tg, getattr(message, "from_user", None)):\n'
