        'def _post_restart_fallback_watcher(\n'
        '    cardinal: Any,\n'
        '    delay_seconds: float = POST_RESTART_FALLBACK_DELAY_SECONDS,\n'
        '    post_init_event: Optional[threading.Event] = None,\n'
        '    wake_event: Optional[threading.Event] = None,\n'
        '    stop_event: Optional[threading.Event] = None,\n'
        ') -> bool:\n'
        '    """Wait briefly for Cardinal BIND_TO_POST_INIT; send notice early if another plugin stalls startup."""\n'
        '    post_ev = post_init_event or _POST_INIT_EVENT\n'
        '    wake_ev = wake_event or _POST_RESTART_WAKE_EVENT\n'
        '    stop_ev = stop_event or STOP_EVENT\n'
        '\n'
        '    if delay_seconds > 0 and not post_ev.is_set() and not stop_ev.is_set():\n'
        '        wake_ev.wait(timeout=delay_seconds)\n'
        '\n'
        '    if stop_ev.is_set() or post_ev.is_set():\n'
        '        return False\n'
        '\n'
        '    try:\n'
        '        pending = peek_pending_restart(RESTART_NOTICE_TTL_SECONDS)\n'
        '    except OSError:\n'
        '        logger.exception("Failed checking pending_restart in fallback watcher")\n'
        '        return False\n'
        '    if not pending:\n'
        '        return False\n'
        '\n'
        '    logger.info(\n'
        '        "BIND_TO_POST_INIT did not reach W1bbex Hub within %.1fs; dispatching post-restart notice from pre_init fallback",\n'
        '        delay_seconds,\n'
        '    )\n'
        '    return process_post_restart_notice(cardinal)\n'
        '\n'
        '\n'
        'def _arm_post_restart_fallback(cardinal: Any) -> bool:\n'
        '    """Spawn a daemon fallback watcher when pending_restart exists at pre_init."""\n'
        '    global _FALLBACK_THREAD\n'
        '    try:\n'
        '        pending = peek_pending_restart(RESTART_NOTICE_TTL_SECONDS)\n'
        '    except OSError:\n'
        '        logger.exception("Failed checking pending_restart on pre_init")\n'
        '        return False\n'
        '    if not pending:\n'
        '        return False\n'
        '\n'
        '    with _FALLBACK_THREAD_LOCK:\n'
        '        if _FALLBACK_THREAD is not None and _FALLBACK_THREAD.is_alive():\n'
        '            return False\n'
        '        thread = threading.Thread(\n'
        '            target=_post_restart_fallback_watcher,\n'
        '            args=(cardinal,),\n'
        '            name="W1bbexHubPostRestartFallback",\n'
        '            daemon=True,\n'
        '        )\n'
        '        _FALLBACK_THREAD = thread\n'
        '        thread.start()\n'
        '        logger.info(\n'
        '            "Armed pre_init post-restart fallback watcher (action=%s pid=%s delay=%.1fs)",\n'
        '            pending.get("action"),\n'
        '            pending.get("plugin_id") or "-",\n'
        '            POST_RESTART_FALLBACK_DELAY_SECONDS,\n'
        '        )\n'
        '        return True\n'
        '\n'
        '\n'
        'def custom_init(cardinal: Cardinal) -> None:\n'
        '    """Cardinal BIND_TO_PRE_INIT entry point."""\n'
        '    global _UPDATE_THREAD\n'
        '    configure_file_logging()\n'
        '    process_pending_deletions()\n'
        '    _POST_INIT_EVENT.clear()\n'
        '    _POST_RESTART_WAKE_EVENT.clear()\n'
        '    STOP_EVENT.clear()\n'
        '    controller = init_cardinal(cardinal)\n'
        '    with _UPDATE_THREAD_LOCK:\n'
        '        if _UPDATE_THREAD is None or not _UPDATE_THREAD.is_alive():\n'
        '            thread = threading.Thread(\n'
        '                target=_update_checker_loop,\n'
        '                args=(cardinal, STOP_EVENT),\n'
        '                name="W1bbexHubUpdateChecker",\n'
        '                daemon=True,\n'
        '            )\n'
        '            _UPDATE_THREAD = thread\n'
        '            thread.start()\n'
        '    if controller is not None:\n'
        '        _arm_post_restart_fallback(cardinal)\n'
        '\n'
        '\n'
        'def stop_hub(*_args: Any, **_kwargs: Any) -> None:\n'
        '    """Cardinal BIND_TO_DELETE entry point signaling background loops to stop."""\n'
        '    STOP_EVENT.set()\n'
        '    _POST_RESTART_WAKE_EVENT.set()\n'
