        '    cardinal_root: Optional[str | Path] = None,\n'
        ') -> HubPaths:\n'
        '    """Compute portable Hub paths relative to the Cardinal root directory."""\n'
        '    entry = Path(anchor_file or __file__).resolve()\n'
        '    entry_dir = entry.parent\n'
        '\n'
        '    if cardinal_root is not None:\n'
        '        root_path = Path(cardinal_root).resolve()\n'
