        '    "installed": "на диске",\n'
        '    "manual": "вручную",\n'
        '}\n'
        '\n'
        '\n'
        'def format_command_lines(commands: list[tuple[str, str]]) -> list[str]:\n'
        '    """Build clean individual HTML lines for a plugin\'s command list."""\n'
        '    if not commands:\n'
        '        return []\n'
        '    lines: list[str] = []\n'
        '    for cmd, desc in commands[:5]:\n'
        '        normalized = cmd.strip().lstrip("/")\n'
        '        if not normalized:\n'
        '            continue\n'
        '        clean_desc = " ".join(desc.split())\n'
        '        if clean_desc:\n'
        '            lines.append(f"/{esc(normalized)} — <i>{esc(clean_desc)}</i>")\n'
        '        else:\n'
        '            lines.append(f"/{esc(normalized)}")\n'
        '    if len(commands) > 5:\n'
        '        lines.append(f"<i>и ещё {len(commands) - 5}…</i>")\n'
        '    return lines\n'
        '\n'
        '\n'
        'def format_primary_command(commands: list[tuple[str, str]]) -> Optional[str]:\n'
        '    """Return primary slash command preview (e.g. \'/autosmm\') without noisy auxiliary duplicates."""\n'
        '    if not commands:\n'
        '        return None\n'
        '    cmd = commands[0][0].strip().lstrip("/")\n'
        '    return f"/{cmd}" if cmd else None\n'
        '\n'
        '\n'
        'def resolve_display_version(state: dict[str, Any]) -> str:\n'
        '    """Pick the most informative current version string for display."""\n'
        '    return str(\n'
        '        state.get("loaded_version")\n'
        '        or state.get("installed_version")\n'
        '        or state.get("latest_version")\n'
        '        or "1.0"\n'
        '    )\n'
        '\n'
        '\n'
        'def format_catalog_line(state: dict[str, Any]) -> str:\n'
        '    """Render one crisp tree line for a plugin inside the catalog overview."""\n'
        '    status = str(state.get("status_code") or "not_installed")\n'
        '    name_html = f"<b>{esc(state.get(\'name\') or state.get(\'id\'))}</b>"\n'
        '    latest = str(state.get("latest_version") or "1.0")\n'
        '    primary_cmd = format_primary_command(state.get("commands") or [])\n'
        '    cmd_part = f" · {esc(primary_cmd)}" if primary_cmd else ""\n'
        '\n'
        '    if status == "not_installed":\n'
        '        if state.get("is_free"):\n'
        '            icon, access = "🆓", "бесплатный"\n'
        '        elif state.get("has_key"):\n'
        '            icon, access = "🔑", "ключ сохранён"\n'
        '        else:\n'
        '            icon, access = "📦", "по ключу"\n'
        '        return f"{icon} {name_html} · {code(latest)} — {access}"\n'
        '\n'
        '    if state.get("has_update") and not state.get("needs_restart"):\n'
        '        curr = str(state.get("installed_version") or state.get("loaded_version") or "?")\n'
        '        return f"⬆️ {name_html} · {code(f\'{curr} → {latest}\')} — есть обновление{cmd_part}"\n'
        '\n'
        '    icon, _ = STATUS_BADGES.get(status, ("🔹", ""))\n'
        '    short_label = SHORT_STATUS_LABELS.get(status, status)\n'
        '    curr_ver = resolve_display_version(state)\n'
        '    return f"{icon} {name_html} · {code(curr_ver)} — {short_label}{cmd_part}"\n'
        '\n'
        '\n'
        'def format_catalog_button(state: dict[str, Any]) -> tuple[str, Optional[str]]:\n'
        '    """Return concise inline button text and semantic Bot API style for a catalog item."""\n'
        '    name = str(state.get("name") or state.get("id") or "")\n'
        '    status = str(state.get("status_code") or "not_installed")\n'
        '    latest = str(state.get("latest_version") or "1.0")\n'
        '    curr = resolve_display_version(state)\n'
        '\n'
        '    if state.get("needs_restart"):\n'
        '        return f"🔄 {name} · рестарт", "success"\n'
        '    if state.get("has_update"):\n'
        '        return f"⬆️ {name} · {latest}", "success"\n'
        '    if status == "broken_files":\n'
        '        return f"⚠️ {name} · ошибка", "danger"\n'
        '    if status == "active":\n'
