        '    if status == "manual":\n'
        '        return f"🔧 {name} · {curr}", None\n'
        '    if status == "installed":\n'
        '        return f"📦 {name} · {curr}", None\n'
        '    if state.get("has_key"):\n'
        '        return f"🔑 {name} · готов", "primary"\n'
        '    if state.get("is_free"):\n'
        '        return f"🆓 {name} · {latest}", None\n'
        '    return f"📦 {name} · {latest}", None\n'
        '\n'
        '\n'
        'def license_summary_text(state: dict[str, Any]) -> str:\n'
        '    """Render concise HTML license status for a plugin detail card."""\n'
        '    if state.get("is_free"):\n'
        '        return "🆓 Бесплатный плагин"\n'
        '    if state.get("has_key"):\n'
