        '\n'
        '\n'
        'def code(value: Any) -> str:\n'
        '    """Wrap escaped text in inline monospace HTML tags."""\n'
        '    return f"<code>{esc(value)}</code>"\n'
        '\n'
        '\n'
        'def italic(value: Any) -> str:\n'
        '    """Wrap escaped text in HTML italic tags."""\n'
        '    return f"<i>{esc(value)}</i>"\n'
        '\n'
        '\n'
        'def link(url: str, label: str) -> str:\n'
        '    """Render an HTML hyperlink with escaped URL and label."""\n'
        '    return f\'<a href="{esc(url)}">{esc(label)}</a>\'\n'
        '\n'
        '\n'
        '_TG_ALLOWED_HTML_TAGS: frozenset[str] = frozenset(\n'
        '    {\n'
        '        "b",\n'
        '        "strong",\n'
        '        "i",\n'
        '        "em",\n'
        '        "u",\n'
        '        "ins",\n'
        '        "s",\n'
        '        "strike",\n'
        '        "del",\n'
        '        "code",\n'
        '        "pre",\n'
        '        "blockquote",\n'
        '        "tg-spoiler",\n'
        '        "a",\n'
        '    }\n'
        ')\n'
        '_TG_SAFE_URL_PREFIXES: tuple[str, ...] = ("http://", "https://", "tg://")\n'
        '_STD_HTML_ENTITIES: frozenset[str] = frozenset({"lt", "gt", "amp", "quot"})\n'
        '\n'
        '\n'
        'class _TelegramHTMLSanitizer(HTMLParser):\n'
        '    """Sanitize server-provided descriptions into safe, balanced Telegram HTML."""\n'
        '\n'
        '    def __init__(self, source: str) -> None:\n'
        '        super().__init__(convert_charrefs=False)\n'
        '        self._source = source\n'
        '        self._line_starts: list[int] = [0]\n'
        '        for idx, ch in enumerate(source):\n'
        '            if ch == "\\n":\n'
        '                self._line_starts.append(idx + 1)\n'
        '        self._out: list[str] = []\n'
        '        # Stack entries: (tag_lower, was_emitted)\n'
        '        self._stack: list[tuple[str, bool]] = []\n'
        '\n'
        '    def _raw_endtag(self, tag: str) -> str:\n'
        '        lineno, col = self.getpos()\n'
        '        if 1 <= lineno <= len(self._line_starts):\n'
        '            start = self._line_starts[lineno - 1] + col\n'
        '            end = self._source.find(">", start)\n'
        '            if end != -1:\n'
        '                return self._source[start : end + 1]\n'
        '        return f"</{tag}>"\n'
        '\n'
        '    def handle_starttag(self, tag: str, attrs: list[tuple[str, Optional[str]]]) -> None:\n'
        '        lower = tag.lower()\n'
        '        raw_tag = self.get_starttag_text() or f"<{tag}>"\n'
        '        if lower not in _TG_ALLOWED_HTML_TAGS:\n'
        '            self._out.append(esc(raw_tag))\n'
        '            return\n'
        '\n'
        '        if lower == "blockquote":\n'
        '            if any(open_tag == "blockquote" and emitted for open_tag, emitted in self._stack):\n'
        '                self._stack.append(("blockquote", False))\n'
        '                return\n'
        '            expandable = any(k.lower() == "expandable" for k, _ in attrs)\n'
        '            self._out.append("<blockquote expandable>" if expandable else "<blockquote>")\n'
        '            self._stack.append(("blockquote", True))\n'
        '            return\n'
        '\n'
        '        if lower == "a":\n'
        '            href = next((v for k, v in attrs if k.lower() == "href" and isinstance(v, str)), "")\n'
        '            href_clean = href.strip()\n'
        '            if href_clean.lower().startswith(_TG_SAFE_URL_PREFIXES):\n'
        '                self._out.append(f\'<a href="{esc(href_clean)}">\')\n'
        '                self._stack.append(("a", True))\n'
        '            else:\n'
        '                self._out.append(esc(raw_tag))\n'
        '                self._stack.append(("a", False))\n'
        '            return\n'
        '\n'
        '        self._out.append(f"<{lower}>")\n'
        '        self._stack.append((lower, True))\n'
        '\n'
        '    def handle_endtag(self, tag: str) -> None:\n'
        '        lower = tag.lower()\n'
        '        match_idx = -1\n'
