        '                break\n'
        '        if match_idx == -1:\n'
        '            self._out.append(esc(self._raw_endtag(tag)))\n'
        '            return\n'
        '\n'
        '        while len(self._stack) - 1 > match_idx:\n'
        '            unclosed_tag, emitted = self._stack.pop()\n'
        '            if emitted:\n'
        '                self._out.append(f"</{unclosed_tag}>")\n'
        '\n'
        '        matched_tag, emitted = self._stack.pop()\n'
        '        if emitted:\n'
        '            self._out.append(f"</{matched_tag}>")\n'
        '        elif matched_tag != "blockquote":\n'
        '            self._out.append(esc(self._raw_endtag(tag)))\n'
