        'class StyledButton(InlineKeyboardButton):\n'
        '    """InlineKeyboardButton subclass preserving Telegram Bot API `style` field in JSON payloads."""\n'
        '\n'
        '    def __init__(\n'
        '        self,\n'
        '        text: str,\n'
        '        callback_data: Optional[str] = None,\n'
        '        url: Optional[str] = None,\n'
        '        style: Optional[ButtonStyle] = None,\n'
        '        **kwargs: Any,\n'
        '    ) -> None:\n'
        '        normalized_style = style if style in VALID_BUTTON_STYLES else None\n'
        '        super().__init__(text=text, callback_data=callback_data, url=url, **kwargs)\n'
