        '\n'
        'def build_kb_rows(rows: list[list[tuple[str, Optional[str], Optional[str], Optional[ButtonStyle]] | tuple[str, Optional[str], Optional[str]]]]) -> InlineKeyboardMarkup:\n'
        '    """Construct an InlineKeyboardMarkup from legacy 3-tuples or styled 4-tuples."""\n'
        '    kb = KeyboardBuilder()\n'
        '    for row in rows:\n'
