        '\n'
        'class CardBuilder:\n'
        '    """Structured Telegram HTML message builder following clean tree hierarchy."""\n'
        '\n'
        '    def __init__(self, icon: str, heading: str, version_badge: Optional[str] = None) -> None:\n'
        '        header = f"{icon} <b>{esc(heading)}</b>" if icon else f"<b>{esc(heading)}</b>"\n'
        '        if version_badge:\n'
        '            header = f"{header} <code>{esc(version_badge)}</code>"\n'
        '        self._blocks: list[str] = [header]\n'
        '\n'
        '    def quote(self, html_body: str, expandable: bool = False) -> CardBuilder:\n'
        '        """Append a pre-formatted HTML blockquote block when non-empty."""\n'
        '        stripped = html_body.strip()\n'
        '        if stripped:\n'
        '            tag = "<blockquote expandable>" if expandable else "<blockquote>"\n'
        '            self._blocks.append(f"{tag}{stripped}</blockquote>")\n'
        '        return self\n'
        '\n'
        '    def paragraph(self, html_text: str) -> CardBuilder:\n'
        '        """Append an HTML paragraph block when non-empty."""\n'
        '        stripped = html_text.strip()\n'
        '        if stripped:\n'
        '            self._blocks.append(stripped)\n'
        '        return self\n'
        '\n'
        '    def tree(self, title_html: Optional[str], items_html: Sequence[str]) -> CardBuilder:\n'
        '        """Append a section with optional bold header and ├/└ tree items."""\n'
        '        cleaned = [item for item in items_html if item]\n'
        '        if not cleaned:\n'
        '            return self\n'
        '        lines: list[str] = []\n'
        '        if title_html:\n'
        '            lines.append(title_html)\n'
        '        lines.extend(render_tree_lines(cleaned))\n'
        '        self._blocks.append("\\n".join(lines))\n'
        '        return self\n'
        '\n'
        '    def build(self) -> str:\n'
        '        """Join non-empty blocks with clean spacing."""\n'
        '        return "\\n\\n".join(block for block in self._blocks if block)\n'
